"""Tests for the seed-resolved RCP stiffness-ladder audit (m22796).

The audit decides a *physical* acceptance verdict from an extrapolation, so the
tests have to prove two different things:

* the estimator recovers a ladder that was generated by a known
  ``phi = phi_inf + A k_n^-p`` law (identity test -- otherwise a "limit" could
  be an artefact of the optimiser);
* the interval reported for that limit actually covers the truth at the claimed
  level (calibration test -- an interval that is too narrow would turn noise
  into a verdict, which is precisely the defect the audit exists to remove).
"""
from __future__ import annotations

import math
import os
import sys

import numpy as np
import pytest

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), ".."))
sys.path.insert(0, os.path.join(ROOT, "src"))
sys.path.insert(0, os.path.join(ROOT, "benchmarks", "case_rcp_deposition"))

import stiffness_seed_audit as ssa  # noqa: E402


KN = [4000.0, 16000.0, 64000.0, 256000.0]
PHI_INF = 0.63660
AMP = 6.0
P_TRUE = 1.0


def _ladder(phi_inf=PHI_INF, amp=AMP, p=P_TRUE, sigma=0.0, seed=0,
            levels=None):
    """Synthetic ``phi(kn)`` law as run dicts (one seed per level by default)."""
    levels = levels or KN
    rng = np.random.default_rng(seed)
    runs = []
    for kn in levels:
        phi = phi_inf + amp * kn ** (-p)
        if sigma:
            phi += float(rng.normal(0.0, sigma))
        runs.append({"mu": 0.0, "kn": kn, "seed": 1, "n": ssa.N_PRIMARY,
                     "phi": phi, "path": "synthetic"})
    return runs


# --------------------------------------------------------------------------
# levels()
# --------------------------------------------------------------------------
def test_levels_aggregate_seeds_and_flag_single_seed_levels():
    runs = []
    for phi in (0.6400, 0.6404, 0.6396):          # mu=0, kn=4000: 3 seeds
        runs.append({"mu": 0.0, "kn": 4000.0, "seed": len(runs) + 1,
                     "phi": phi, "n": 10000, "path": "x"})
    runs.append({"mu": 0.0, "kn": 16000.0, "seed": 1, "phi": 0.6375,
                 "n": 10000, "path": "x"})
    runs.append({"mu": 0.1, "kn": 4000.0, "seed": 1, "phi": 0.6260,
                 "n": 10000, "path": "x"})
    lv = ssa.levels(runs, 0.0)
    assert [l["kn"] for l in lv] == [4000.0, 16000.0]
    assert lv[0]["n"] == 3 and lv[0]["err_model"] == "seed"
    assert lv[0]["mean"] == pytest.approx(0.64, abs=1e-12)
    assert lv[0]["sem"] == pytest.approx(4e-4 / math.sqrt(3), rel=1e-9)
    assert lv[0]["df"] == 2
    # the single-seed level must borrow the pooled s and say so
    assert lv[1]["n"] == 1 and lv[1]["err_model"] == "pooled_sd"
    assert lv[1]["sem"] == pytest.approx(lv[0]["sd"], rel=1e-12)
    assert lv[1]["df"] == lv[0]["df"]
    # the other friction tier is untouched
    assert [l["kn"] for l in ssa.levels(runs, 0.1)] == [4000.0]


def test_levels_seed1_value_is_seed_matched_not_the_smallest():
    runs = [
        {"mu": 0.0, "kn": 4000.0, "seed": 3, "phi": 0.6401, "n": 10000, "path": "x"},
        {"mu": 0.0, "kn": 4000.0, "seed": 1, "phi": 0.6417, "n": 10000, "path": "x"},
        {"mu": 0.0, "kn": 64000.0, "seed": 1, "phi": 0.6360, "n": 10000, "path": "x"},
    ]
    lv = ssa.levels(runs, 0.0)
    assert lv[0]["phi_seed1"] == pytest.approx(0.6417)


# --------------------------------------------------------------------------
# fit_ladder()
# --------------------------------------------------------------------------
def test_fit_recovers_known_law_without_noise():
    lv = ssa.levels(_ladder(sigma=0.0), 0.0)
    pts = [(l["kn"], l["mean"], 1e-6) for l in lv]
    f = ssa.fit_ladder(pts)
    assert f["phi_inf"] == pytest.approx(PHI_INF, abs=2e-5)
    assert f["p"] == pytest.approx(P_TRUE, rel=0.05)
    assert f["chi2_red"] < 1e-6
    # fixed order must give the same intercept when the order is correct
    f1 = ssa.fit_ladder(pts, p_fixed=1.0)
    assert f1["phi_inf"] == pytest.approx(PHI_INF, abs=2e-5)


def test_fit_needs_two_levels_and_positive_sigma():
    with pytest.raises(ValueError):
        ssa.fit_ladder([(4000.0, 0.64, 1e-4)])
    with pytest.raises(ValueError):
        ssa.fit_ladder([(4000.0, 0.64, 0.0), (16000.0, 0.636, 1e-4)])


def test_fit_is_insensitive_to_point_order():
    lv = ssa.levels(_ladder(sigma=1e-4, seed=5), 0.0)
    pts = [(l["kn"], l["mean"], 1e-4) for l in lv]
    a = ssa.fit_ladder(pts)
    b = ssa.fit_ladder(list(reversed(pts)))
    assert a["phi_inf"] == pytest.approx(b["phi_inf"], abs=1e-12)
    assert a["p"] == pytest.approx(b["p"], abs=1e-9)


def test_fit_prefers_the_linear_spring_order_for_an_overlap_ladder():
    """A linear-spring soft bed has ``phi = phi_inf - C/k_n`` exactly."""
    phi_inf, c = 0.6366, 8.0
    runs = [{"mu": 0.0, "kn": kn, "seed": 1, "n": 10000,
             "phi": phi_inf - c / kn, "path": "x"} for kn in KN]
    lv = ssa.levels(runs, 0.0)
    f = ssa.fit_ladder([(l["kn"], l["mean"], 1e-6) for l in lv])
    assert f["phi_inf"] == pytest.approx(phi_inf, abs=1e-5)
    assert f["p"] == pytest.approx(1.0, rel=0.02)


# --------------------------------------------------------------------------
# judge_band() / definition_spread()
# --------------------------------------------------------------------------
@pytest.mark.parametrize("lo,hi,expect", [
    (0.630, 0.640, "IN_BAND"),
    (0.610, 0.619, "OUT_OF_BAND"),
    (0.615, 0.623, "UNDECIDABLE"),
    (0.665, 0.670, "OUT_OF_BAND"),
    (None, None, "NO_INTERVAL"),
])
def test_judge_band_is_interval_based(lo, hi, expect):
    assert ssa.judge_band(lo, hi) == expect


def test_judge_band_never_passes_a_point_estimate_below_the_band():
    # 0.6193 is inside no band; a zero-width interval must say OUT_OF_BAND,
    # not IN_BAND with a warning.
    assert ssa.judge_band(0.6193, 0.6193) == "OUT_OF_BAND"


def test_definition_spread_reports_all_ladder_definitions():
    lv = ssa.levels(_ladder(sigma=3e-4, seed=3), 0.0)
    d = ssa.definition_spread(lv)
    for key in ("seed1_chain", "seedmean_chain", "drop_stiffest", "p_fixed_1"):
        assert key in d, key
        assert math.isfinite(d[key]["phi_inf"])
    assert d["_spread"] > 0.0
    # dropping the stiffest level must move the intercept by less than the
    # soft-bed systematic it is meant to remove (here ~2e-3 over the ladder)
    assert abs(d["drop_stiffest"]["phi_inf"] - d["seedmean_chain"]["phi_inf"]) < 5e-3


# --------------------------------------------------------------------------
# limit_interval(): calibration
# --------------------------------------------------------------------------
def test_interval_covers_the_truth_at_the_claimed_level():
    """40 independent noisy ladders: the 95 % interval must cover ``phi_inf``.

    Measured coverage of this construction on a 3-seed ladder is 54/60 = 90 %
    (the residual gap to the nominal 95 % is the finite-dof error of the
    per-level ``s``), so the acceptance threshold is 85 % -- loose enough not to
    flake, tight enough to fail an interval that is grossly too narrow (a
    2x-too-narrow interval covers ~68 %).
    """
    sigma = 3e-4
    hits = 0
    trials = 40
    rng = np.random.default_rng(11)
    for _ in range(trials):
        runs = []
        for kn in KN:
            for s in (1, 2, 3):
                phi = PHI_INF + AMP * kn ** (-P_TRUE) + float(rng.normal(0, sigma))
                runs.append({"mu": 0.0, "kn": kn, "seed": s, "n": 10000,
                             "phi": phi, "path": "x"})
        ci = ssa.limit_interval(ssa.levels(runs, 0.0), n_mc=150, p_fixed=1.0)
        assert ci["lo"] < ci["hi"]
        if ci["lo"] <= PHI_INF <= ci["hi"]:
            hits += 1
    assert hits >= int(0.85 * trials), f"only {hits}/{trials} intervals covered"


def test_interval_widens_when_replicates_are_sparse():
    """A level with a single seed must produce a wider interval than a full one."""
    full = []
    for kn in KN:
        for s in (1, 2, 3):
            full.append({"mu": 0.0, "kn": kn, "seed": s, "n": 10000,
                         "phi": PHI_INF + AMP * kn ** (-P_TRUE)
                                 + 3e-4 * (s - 2), "path": "x"})
    sparse = [r for r in full if not (r["kn"] == KN[-1] and r["seed"] != 1)]
    wide = ssa.limit_interval(ssa.levels(sparse, 0.0), n_mc=200, p_fixed=1.0)
    narrow = ssa.limit_interval(ssa.levels(full, 0.0), n_mc=200, p_fixed=1.0)
    assert wide["hi"] - wide["lo"] > narrow["hi"] - narrow["lo"]
    assert wide["pooled_levels"] == [KN[-1]] and not narrow["pooled_levels"]


def test_ladder_without_any_replicate_reports_no_interval():
    """Noise-free bookkeeping must not masquerade as a certified limit.

    A ladder of single-seed points has no way to estimate the scatter; the audit
    must then decline to give an interval (``NO_INTERVAL``) instead of quoting a
    zero-width one -- the defect that made the pre-m22796 point-estimate gate
    unable to tell ``|Delta| = 6.8e-4`` from seed noise.
    """
    lv = ssa.levels(_ladder(sigma=1e-4, seed=2), 0.0)
    assert all(l["err_model"] == "no_noise" for l in lv)
    ci = ssa.limit_interval(lv, n_mc=50)
    assert ci["noise_available"] is False
    assert ci["lo"] is None and ssa.judge_band(ci["lo"], ci["hi"]) == "NO_INTERVAL"
    assert math.isfinite(ci["phi_inf"])


# --------------------------------------------------------------------------
# end-to-end on the artefacts on disk
# --------------------------------------------------------------------------
def test_audit_on_disk_artefacts_is_well_formed():
    runs = ssa.load_runs()
    if not runs:
        pytest.skip("no deposition artefacts on disk")
    res = ssa.audit(runs, n_mc=200)
    assert res["band"] == list(ssa.BAND)
    for key, row in res["tiers"].items():
        f = row["fit"]
        assert row["n_levels"] >= 2
        assert math.isfinite(f["phi_inf"])
        assert f["lo"] <= f["phi_inf"] <= f["hi"] or f["lo"] <= f["phi_inf"] <= f["hi"]
        assert row["verdict_band"] in ("IN_BAND", "OUT_OF_BAND", "UNDECIDABLE")
        assert all(r["n"] == ssa.N_PRIMARY for r in runs)